head.b:skin:
:root{--pri:#123d73;--pri-d:#0b2445;--acc:#f7c928;--text:#172033;--muted:#687386;--bd:#e4e8ee;--bg:#fff;--bg2:#f5f7fa;--card:#fff;--link:#123d73;--hh:64px;--r:10px;--sh:0 2px 10px rgba(11,36,69,.08);--serif:Georgia,'Times New Roman',serif;--sans:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif}
[data-theme='dark']{--bg:#0b1220;--bg2:#111a2e;--card:#111a2e;--text:#e8edf5;--muted:#9aa7bd;--bd:#22304a;--link:#8db8ff;--sh:0 2px 10px rgba(0,0,0,.4)}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--hh) + 12px)}
body{margin:0;font-family:var(--sans);background:var(--bg);color:var(--text);line-height:1.65;font-size:16px;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4,p,ul,ol,figure,blockquote{margin:0}
a{color:inherit;text-decoration:none}
a:hover{color:var(--link)}
img{max-width:100%;height:auto;display:block}
button{font:inherit;cursor:pointer}
.section,.widget{margin:0;padding:0}
.widget ul,.widget ol{list-style:none;margin:0;padding:0}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 1rem}
.ad-src{position:absolute;visibility:hidden;left:0;right:0;height:0;overflow:hidden}
/* top bar */
.topbar{background:var(--pri-d);color:#b9c6da;font-size:.78rem}
.topbar-in{display:flex;justify-content:space-between;align-items:center;min-height:32px}
.topbar a{margin-left:1rem;color:#b9c6da}.topbar a:hover{color:var(--acc)}
/* header */
.site-header{position:sticky;top:0;z-index:100;background:var(--pri);color:#fff;height:var(--hh);box-shadow:0 2px 8px rgba(0,0,0,.18)}
.header-in{display:flex;align-items:center;gap:1.25rem;height:100%}
.logo{flex:0 0 auto}
.logo a{font-family:var(--serif);font-weight:800;font-size:1.45rem;letter-spacing:-.02em;color:#fff}
.logo a:hover{color:var(--acc)}
.logo img{max-height:40px;width:auto}
.logo h1{font-size:inherit;margin:0}
.nav-desktop{flex:1;display:none;min-width:0}
.nav-desktop .widget{display:flex;flex-wrap:nowrap;gap:.15rem}
.nav-desktop a{padding:.5rem .8rem;font-size:.9rem;font-weight:600;color:#dbe5f4;border-radius:6px;white-space:nowrap}
.nav-desktop a:hover{background:rgba(255,255,255,.1);color:var(--acc)}
.actions{display:flex;align-items:center;gap:.5rem;margin-left:auto}
.icon-btn{width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,.25);background:transparent;color:#fff;display:flex;align-items:center;justify-content:center;padding:0}
.icon-btn:hover{background:rgba(255,255,255,.12);border-color:var(--acc)}
.icon-btn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.i-sun{display:none}[data-theme='dark'] .i-sun{display:block}[data-theme='dark'] .i-moon{display:none}
.btn-acc{display:none;background:var(--acc);color:#1a1a1a;font-weight:700;font-size:.85rem;padding:.5rem 1rem;border-radius:999px}
.btn-acc:hover{background:#fff;color:var(--pri-d)}
.mobile-menu{position:fixed;top:var(--hh);left:0;right:0;background:var(--pri-d);z-index:99;padding:.5rem 0 1rem;transform:translateY(-120%);transition:transform .25s ease;max-height:calc(100vh - var(--hh));overflow:auto}
.mobile-menu.is-open{transform:none}
.mobile-menu a{display:block;padding:.8rem 1.25rem;color:#fff;font-weight:600;border-bottom:1px solid rgba(255,255,255,.08)}
.mobile-menu a:hover{color:var(--acc)}
.search-overlay{position:fixed;top:var(--hh);left:0;right:0;background:var(--pri-d);padding:1rem;z-index:98;display:none;border-top:1px solid rgba(255,255,255,.1)}
.search-overlay.is-open{display:block}
.search-overlay form{display:flex;gap:.5rem;max-width:720px;margin:0 auto}
.search-overlay input{flex:1;min-width:0;padding:.7rem 1rem;border-radius:8px;border:0;font:inherit;background:#fff;color:#111}
.search-overlay button{padding:.7rem 1.1rem;border:0;border-radius:8px;background:var(--acc);font-weight:700;color:#111}
@media(min-width:900px){.nav-desktop{display:block}.btn-acc{display:inline-block}.menu-btn{display:none}}
#progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--acc);z-index:200}
/* ads */
.ad-slot{margin:1rem auto;text-align:center;max-width:100%;overflow:hidden}
.ad-label{display:block;font-size:.62rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:.3rem}
.ad-box{display:flex;align-items:center;justify-content:center;margin:0 auto;border:1px dashed var(--bd);background:var(--bg2);color:var(--muted);font-size:.78rem;min-height:90px;max-width:728px;border-radius:6px;padding:.5rem;text-align:center}
.ad-box.filled{border:0;background:none;padding:0;display:block;min-height:0}
.ad-sq .ad-box{min-height:250px;max-width:300px}
.ad-tall .ad-box{min-height:600px;max-width:300px}
.ad-fluid .ad-box{min-height:120px;max-width:100%}
.ad-infeed{grid-column:1/-1;margin:0}
/* blocks */
.block-title{display:flex;justify-content:space-between;align-items:center;font-size:1.05rem;font-weight:800;text-transform:uppercase;letter-spacing:.03em;border-bottom:2px solid var(--bd);margin-bottom:.9rem;position:relative}
.block-title span{display:inline-block;padding:.35rem 0;border-bottom:3px solid var(--acc);margin-bottom:-2px;color:var(--text)}
.block-title a{font-size:.72rem;font-weight:600;color:var(--muted);text-transform:none;letter-spacing:0}
.badge{display:inline-block;background:var(--acc);color:#1a1a1a;font-size:.68rem;font-weight:800;text-transform:uppercase;letter-spacing:.05em;padding:.2rem .55rem;border-radius:4px;line-height:1.3}
.meta{display:flex;flex-wrap:wrap;gap:.4rem;align-items:center;font-size:.8rem;color:var(--muted)}
/* home top */
.home-top{margin-top:1rem}
.top-grid{display:grid;gap:1rem}
@media(min-width:900px){.top-grid{grid-template-columns:2fr 1fr}}
.hero{position:relative;display:block;border-radius:var(--r);overflow:hidden;min-height:340px;background:var(--pri-d) center/cover no-repeat;color:#fff}
@media(min-width:900px){.hero{min-height:420px;height:100%}}
.hero::after{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(5,15,32,.92),rgba(5,15,32,.1) 65%)}
.hero-in{position:absolute;left:0;right:0;bottom:0;padding:1.25rem;z-index:1}
.hero h2{font-family:var(--serif);font-size:clamp(1.35rem,3.4vw,2.1rem);line-height:1.2;margin:.5rem 0;color:#fff}
.hero p{color:#d3dcec;font-size:.92rem;max-width:620px}
.hero .meta{color:#c4d0e4;margin-top:.5rem}
.hero:hover{color:#fff}
.promo{position:relative;border-radius:var(--r);overflow:hidden;min-height:260px;height:100%;background:linear-gradient(135deg,var(--pri),var(--pri-d));color:#fff;display:flex}
.promo img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.35}
.promo-in{position:relative;padding:1.5rem;display:flex;flex-direction:column;justify-content:flex-end;gap:.6rem}
.promo h3{font-family:var(--serif);font-size:1.45rem;line-height:1.2;color:#fff}
.promo p{font-size:.9rem;color:#d3dcec}
.promo .btn-acc{display:inline-block;align-self:flex-start}
.cat-grid{display:grid;gap:1.5rem;margin:1.5rem 0 0}
@media(min-width:800px){.cat-grid{grid-template-columns:1fr 1fr}}
.cat-big{display:block;margin-bottom:.8rem}
.cat-big .thumb{aspect-ratio:16/9;border-radius:8px;overflow:hidden;background:var(--bg2);margin-bottom:.6rem}
.cat-big img,.row img,.card-thumb img{width:100%;height:100%;object-fit:cover;transition:transform .4s}
.cat-big:hover img,.row:hover img,.card:hover img{transform:scale(1.05)}
.cat-big h3{font-family:var(--serif);font-size:1.2rem;line-height:1.3;margin-bottom:.25rem}
.cat-big p{font-size:.88rem;color:var(--muted)}
.row{display:flex;gap:.75rem;padding:.65rem 0;border-top:1px solid var(--bd)}
.row .thumb{flex:0 0 88px;height:66px;border-radius:6px;overflow:hidden;background:var(--bg2)}
.row h4{font-size:.92rem;line-height:1.35;font-weight:700}
.row .n{flex:0 0 auto;font-family:var(--serif);font-size:1.5rem;font-weight:800;color:var(--acc);line-height:1;min-width:1.4rem}
[data-feed]{min-height:120px}
[data-feed].loaded{min-height:0}
.skel{height:100px;border-radius:8px;background:linear-gradient(90deg,var(--bg2),var(--bd),var(--bg2));background-size:200% 100%;animation:sk 1.2s infinite}
@keyframes sk{to{background-position:-200% 0}}
/* layout */
.layout{display:grid;gap:1.5rem;margin-top:1.25rem;margin-bottom:1.5rem}
@media(min-width:992px){.layout{grid-template-columns:minmax(0,1fr) 320px}}
.content{min-width:0}
.sidebar{min-width:0}
.sidebar>.section{display:flex;flex-direction:column;gap:1.25rem;height:100%}
@media(min-width:992px){.sidebar .widget:last-child{position:sticky;top:calc(var(--hh) + 1rem)}}
.side-box{background:var(--card);border:1px solid var(--bd);border-radius:var(--r);padding:1rem}
.side-box .block-title{margin-bottom:.6rem}
.side-search{display:flex;gap:.4rem}
.side-search input{flex:1;min-width:0;padding:.6rem .8rem;border:1px solid var(--bd);border-radius:8px;background:var(--bg);color:var(--text);font:inherit}
.side-search button{border:0;background:var(--pri);color:#fff;border-radius:8px;padding:0 .9rem;font-weight:700}
.tags{display:flex;flex-wrap:wrap;gap:.4rem}
.tags a{font-size:.8rem;padding:.25rem .65rem;border:1px solid var(--bd);border-radius:999px;background:var(--bg2)}
.tags a:hover{background:var(--pri);color:#fff;border-color:var(--pri)}
.page-title{margin-bottom:.9rem}
.archive-head{background:var(--bg2);border-left:5px solid var(--acc);border-radius:var(--r);padding:1.1rem 1.25rem;margin-bottom:1rem}
.kicker{font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}
.archive-head h1{font-family:var(--serif);font-size:clamp(1.5rem,4vw,2.2rem);line-height:1.2}
/* cards */
.posts-grid{display:grid;gap:1.1rem;grid-template-columns:1fr}
@media(min-width:640px){.posts-grid{grid-template-columns:1fr 1fr}}
.card{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--bd);border-radius:var(--r);overflow:hidden;transition:box-shadow .2s,transform .2s}
.card:hover{box-shadow:var(--sh);transform:translateY(-2px)}
.card-thumb{position:relative;display:block;aspect-ratio:16/9;overflow:hidden;background:var(--bg2)}
.card-thumb .ph{position:absolute;inset:0;background:linear-gradient(135deg,var(--pri),var(--pri-d))}
.card-thumb .badge{position:absolute;left:.6rem;top:.6rem;z-index:1}
.card-body{padding:.9rem 1rem 1rem;display:flex;flex-direction:column;gap:.35rem;flex:1}
.card-title{font-family:var(--serif);font-size:1.12rem;line-height:1.3}
.card-snip{font-size:.88rem;color:var(--muted);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.pager{display:flex;justify-content:space-between;gap:.75rem;margin-top:1.25rem}
.pager a{display:inline-block;padding:.6rem 1.2rem;border-radius:999px;background:var(--pri);color:#fff;font-weight:700;font-size:.88rem}
.pager a:hover{background:var(--acc);color:#111}
.pager .sp{flex:1}
/* post */
.post-detail{min-width:0}
.crumbs{display:flex;flex-wrap:wrap;gap:.4rem;font-size:.8rem;color:var(--muted);margin-bottom:.8rem}
.crumbs a:hover{color:var(--link)}
.crumbs .cur{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.post-h1{font-family:var(--serif);font-size:clamp(1.65rem,4.5vw,2.6rem);line-height:1.2;margin:.55rem 0 .7rem;letter-spacing:-.01em}
.meta.big{font-size:.86rem;gap:.55rem;padding-bottom:.9rem;border-bottom:1px solid var(--bd);margin-bottom:1rem}
.avatar{width:30px;height:30px;border-radius:50%;background:var(--pri);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:.8rem}
.post-hero{margin:0 0 1rem}
.post-hero img{width:100%;border-radius:var(--r);aspect-ratio:16/9;object-fit:cover}
.post-body{font-size:1.06rem;line-height:1.8;overflow-wrap:break-word}
.post-body p{margin-bottom:1.1rem}
.post-body h2,.post-body h3,.post-body h4{font-family:var(--serif);line-height:1.3;margin:1.8rem 0 .7rem}
.post-body img{border-radius:8px;margin:1rem auto}
.post-body a{color:var(--link);text-decoration:underline}
.post-body ul,.post-body ol{margin:0 0 1.1rem 1.4rem;padding:0;list-style:revert}
.post-body li{margin-bottom:.3rem}
.post-body blockquote{border-left:4px solid var(--acc);background:var(--bg2);padding:.8rem 1.1rem;margin:1.2rem 0;font-style:italic;border-radius:0 8px 8px 0}
.post-body pre,.post-body code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:.88em}
.post-body pre{background:#0b1220;color:#e6edf7;padding:1rem;border-radius:8px;overflow:auto;margin-bottom:1.1rem}
.post-body table{border-collapse:collapse;width:100%;display:block;overflow-x:auto;margin-bottom:1.1rem}
.post-body th,.post-body td{border:1px solid var(--bd);padding:.5rem .7rem;text-align:left}
.post-body iframe,.post-body video{max-width:100%}
.post-foot{display:flex;flex-wrap:wrap;gap:.6rem 1rem;align-items:center;justify-content:space-between;margin:1.25rem 0;padding:.9rem 0;border-top:1px solid var(--bd);border-bottom:1px solid var(--bd)}
.share{display:flex;gap:.4rem;flex-wrap:wrap;align-items:center;font-size:.8rem;font-weight:700}
.share a,.share button{border:0;background:var(--pri);color:#fff;padding:.35rem .8rem;border-radius:999px;font-size:.78rem;font-weight:700}
.share a:hover,.share button:hover{background:var(--acc);color:#111}
.author-box{display:flex;gap:.9rem;align-items:center;background:var(--bg2);border-radius:var(--r);padding:1rem;margin-bottom:1.25rem}
.author-box .avatar{width:52px;height:52px;font-size:1.3rem;flex:0 0 auto}
.author-box b{display:block}
.author-box span.d{font-size:.86rem;color:var(--muted)}
.related{margin:1.5rem 0}
.rel-grid{display:grid;gap:1rem;grid-template-columns:1fr 1fr}
@media(min-width:700px){.rel-grid{grid-template-columns:repeat(3,1fr)}}
.rel-grid .card-title{font-size:.95rem}
.comments{margin-top:1.5rem}
.comments h3.title,.comments .title{font-family:var(--serif);font-size:1.3rem;margin-bottom:.8rem}
.comments ol,.comments ul{list-style:none;margin:0;padding:0}
.comments .comment,.comments .comment-block{margin-bottom:.9rem}
.comments .comment-replies{margin-left:1.2rem;padding-left:.8rem;border-left:2px solid var(--bd)}
.comments .avatar-image-container{float:left;margin-right:.7rem}
.comments .avatar-image-container img{border-radius:50%}
.comments .comment-content{font-size:.95rem}
.comments .user{font-weight:700}
.comments .datetime,.comments .comment-actions,.comments .comment-actions a{font-size:.78rem;color:var(--muted)}
.comments iframe{width:100%;border:0}
.comments .comment-form{margin-top:1rem}
.comments .comment-footer a{font-weight:700;color:var(--link)}
/* footer */
.site-footer{background:var(--pri-d);color:#b9c6da;margin-top:1.5rem;padding:2rem 0 1rem;font-size:.9rem}
.footer-grid{display:grid;gap:1.5rem;grid-template-columns:1fr}
@media(min-width:640px){.footer-grid{grid-template-columns:1fr 1fr}}
@media(min-width:992px){.footer-grid{grid-template-columns:1.6fr 1fr 1fr 1fr}}
.site-footer h3{color:#fff;font-size:1rem;margin-bottom:.7rem;border-bottom:2px solid var(--acc);display:inline-block;padding-bottom:.2rem}
.site-footer ul li{margin-bottom:.4rem}
.site-footer a{color:#b9c6da}.site-footer a:hover{color:var(--acc)}
.copyright{margin-top:1.5rem;padding-top:1rem;border-top:1px solid rgba(255,255,255,.12);text-align:center;font-size:.8rem}
#to-top{position:fixed;right:1rem;bottom:1rem;width:42px;height:42px;border-radius:50%;border:0;background:var(--acc);color:#111;font-size:1.1rem;font-weight:800;box-shadow:var(--sh);opacity:0;visibility:hidden;transition:.2s;z-index:90}
#to-top.show{opacity:1;visibility:visible}
@media(max-width:600px){.hero{min-height:300px}.row .thumb{flex-basis:76px;height:58px}}
@media print{.site-header,.topbar,.sidebar,.site-footer,.ad-slot,#to-top,.share,.related,.comments{display:none!important}}


/* ===================== MOTION PACK ===================== */
:root{--ease:cubic-bezier(.22,.75,.25,1);--t-fast:.2s;--t-med:.4s}
::selection{background:var(--acc);color:#111}
:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
body{overflow-x:clip}
a{transition:color .2s}
@keyframes pm-up{from{opacity:0;transform:translateY(30px)}}
@keyframes pm-left{from{opacity:0;transform:translateX(-44px)}}
@keyframes pm-right{from{opacity:0;transform:translateX(44px)}}
@keyframes pm-zoom{from{opacity:0;transform:scale(.93)}}
@keyframes pm-down{from{opacity:0;transform:translateY(-16px)}}
@keyframes pm-drop{from{transform:translateY(-100%)}}
@keyframes pm-spin{to{transform:rotate(360deg)}}
@keyframes pm-pulse{0%{box-shadow:0 0 0 0 rgba(247,201,40,.55)}70%,100%{box-shadow:0 0 0 14px rgba(247,201,40,0)}}
@keyframes pm-rip{to{transform:scale(1);opacity:0}}
@keyframes pm-kb{from{transform:scale(1)}to{transform:scale(1.12) translate(-1.5%,-1%)}}
@keyframes pm-kenin{from{transform:scale(1.12)}}
@keyframes pm-marq{to{transform:translateX(-50%)}}
@keyframes pm-dot{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.7)}}

/* scroll reveal (only active when JS adds .pm-motion + data-rv) */
.pm-motion [data-rv]{opacity:0}
.pm-motion [data-rv].in{opacity:1;animation-duration:.75s;animation-timing-function:var(--ease);animation-delay:var(--d,0s);animation-fill-mode:backwards}
.pm-motion [data-rv=up].in{animation-name:pm-up}
.pm-motion [data-rv=left].in{animation-name:pm-left}
.pm-motion [data-rv=right].in{animation-name:pm-right}
.pm-motion [data-rv=zoom].in{animation-name:pm-zoom}

/* header */
.site-header{animation:pm-drop .6s var(--ease) backwards;transition:box-shadow var(--t-med)}
.site-header.scrolled{box-shadow:0 6px 22px rgba(0,0,0,.28)}
.logo a{display:inline-block;transition:transform var(--t-med) var(--ease),color var(--t-fast)}
.logo a:hover{transform:translateX(4px)}
.nav-desktop a{position:relative;transition:background var(--t-fast),color var(--t-fast)}
.nav-desktop a::after{content:'';position:absolute;left:.8rem;right:.8rem;bottom:.18rem;height:2px;background:var(--acc);transform:scaleX(0);transform-origin:right;transition:transform var(--t-med) var(--ease)}
.nav-desktop a:hover::after,.nav-desktop a:focus-visible::after{transform:scaleX(1);transform-origin:left}
#progress{background:linear-gradient(90deg,var(--acc),#fff3b0);box-shadow:0 0 10px rgba(247,201,40,.7);transition:width .1s linear}
.mobile-menu{transition:transform .35s var(--ease)}
.mobile-menu.is-open a{animation:pm-right .45s var(--ease) backwards;animation-delay:calc(var(--i,0)*.045s + .08s)}
.mobile-menu a{transition:padding-left .25s var(--ease),color .2s}
.mobile-menu a:hover{padding-left:1.75rem}
.search-overlay.is-open{animation:pm-down .3s var(--ease)}
.search-overlay input,.side-search input{transition:box-shadow var(--t-fast),border-color var(--t-fast)}
.search-overlay input:focus{outline:0;box-shadow:0 0 0 3px rgba(247,201,40,.55)}
.side-search input:focus{outline:0;border-color:var(--pri);box-shadow:0 0 0 3px rgba(18,61,115,.18)}

/* buttons: lift, shine sweep, press, ripple */
.btn-acc,.pager a,.share a,.share button,.side-search button,.search-overlay button,.icon-btn{position:relative;overflow:hidden;-webkit-tap-highlight-color:transparent;transition:transform var(--t-fast) var(--ease),background var(--t-fast),color var(--t-fast),border-color var(--t-fast),box-shadow var(--t-fast)}
.btn-acc:hover,.pager a:hover,.share a:hover,.share button:hover,.side-search button:hover,.search-overlay button:hover{transform:translateY(-2px);box-shadow:0 6px 14px rgba(0,0,0,.22)}
.icon-btn:hover{transform:translateY(-2px)}
.btn-acc:active,.pager a:active,.share a:active,.share button:active,.side-search button:active,.search-overlay button:active,.icon-btn:active{transform:translateY(0) scale(.96);box-shadow:none}
.btn-acc::before,.pager a::before,.share a::before,.share button::before,.side-search button::before,.search-overlay button::before{content:'';position:absolute;top:0;left:-80%;width:50%;height:100%;background:linear-gradient(110deg,transparent,rgba(255,255,255,.5),transparent);transform:skewX(-20deg);transition:left .65s var(--ease);pointer-events:none}
.btn-acc:hover::before,.pager a:hover::before,.share a:hover::before,.share button:hover::before,.side-search button:hover::before,.search-overlay button:hover::before{left:130%}
.btn-acc{animation:pm-pulse 2.6s ease-out infinite}
.btn-acc:hover{animation:none}
.pager a[rel=prev]:hover{transform:translateX(-4px)}
.pager a[rel=next]:hover{transform:translateX(4px)}
.icon-btn svg{transition:transform .4s var(--ease)}
#search-open:hover svg{transform:scale(1.15) rotate(-8deg)}
#theme-toggle:hover svg{transform:rotate(25deg)}
#theme-toggle.spin svg{animation:pm-spin .6s var(--ease)}
#menu-toggle:hover svg{transform:scaleX(.82)}
.rip{position:absolute;border-radius:50%;background:rgba(255,255,255,.5);transform:scale(0);animation:pm-rip .6s ease-out forwards;pointer-events:none}
#to-top{transform:translateY(24px) scale(.8);transition:opacity .3s,visibility .3s,transform .4s var(--ease),background .2s}
#to-top.show{transform:none}
#to-top.show:hover{transform:translateY(-4px)}

/* trending ticker (sliding marquee) */
.ticker{background:var(--bg2);border-bottom:1px solid var(--bd);font-size:.84rem;min-height:38px;animation:pm-down .6s var(--ease) .2s backwards}
.ticker.off{display:none}
.ticker-in{display:flex;align-items:center;gap:.9rem;min-height:38px}
.ticker-label{flex:0 0 auto;display:inline-flex;align-items:center;gap:.45rem;background:var(--pri);color:#fff;font-weight:800;font-size:.76rem;padding:.22rem .7rem;border-radius:4px}
.ticker-label::before{content:'';width:7px;height:7px;border-radius:50%;background:var(--acc);animation:pm-dot 1.4s ease-in-out infinite}
.ticker-viewport{flex:1;min-width:0;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 3%,#000 97%,transparent);mask-image:linear-gradient(90deg,transparent,#000 3%,#000 97%,transparent)}
.ticker-track{display:inline-flex;white-space:nowrap;width:max-content;animation:pm-marq var(--dur,50s) linear infinite}
.ticker:hover .ticker-track{animation-play-state:paused}
.ticker-track a{position:relative;padding-right:1.4rem;margin-right:1.4rem;color:var(--text);font-weight:600}
.ticker-track a::after{content:'';position:absolute;right:0;top:50%;width:5px;height:5px;margin-top:-2.5px;background:var(--acc);transform:rotate(45deg)}
.ticker-track a:hover{color:var(--link)}

/* hero: slow zoom + staggered text */
.hero{animation:pm-zoom .8s var(--ease) backwards}
.hero::before{content:'';position:absolute;inset:0;background:inherit;animation:pm-kb 22s ease-in-out infinite alternate;will-change:transform}
.hero .badge{animation:pm-left .7s var(--ease) .25s backwards}
.hero h2{animation:pm-up .8s var(--ease) .35s backwards;transition:transform .5s var(--ease)}
.hero p{animation:pm-up .8s var(--ease) .5s backwards}
.hero .meta{animation:pm-up .8s var(--ease) .62s backwards}
.hero:hover h2{transform:translateX(6px)}
.promo::before{content:'';position:absolute;width:220px;height:220px;right:-60px;top:-60px;border-radius:50%;background:radial-gradient(circle,rgba(247,201,40,.55),transparent 70%);animation:pm-float 7s ease-in-out infinite alternate}
@keyframes pm-float{to{transform:translate(-40px,50px) scale(1.2)}}

/* section titles: accent bar slides open */
.block-title span{position:relative;border-bottom:0;padding-bottom:calc(.35rem + 3px)}
.block-title span::after{content:'';position:absolute;left:0;right:0;bottom:0;height:3px;background:var(--acc);transform-origin:left;transition:transform .8s var(--ease) .2s}
.pm-motion .block-title[data-rv]:not(.in) span::after{transform:scaleX(0)}

/* cards, rows, thumbs */
.card{transition:transform var(--t-med) var(--ease),box-shadow var(--t-med),border-color var(--t-med)}
.card:hover{transform:translateY(-6px);box-shadow:0 14px 28px rgba(11,36,69,.16);border-color:var(--acc)}
.cat-big .thumb{position:relative}
.card-thumb::after,.cat-big .thumb::after{content:'';position:absolute;top:0;left:-120%;width:60%;height:100%;background:linear-gradient(105deg,transparent,rgba(255,255,255,.35),transparent);transform:skewX(-18deg);transition:left .8s var(--ease);pointer-events:none;z-index:1}
.card:hover .card-thumb::after,.cat-big:hover .thumb::after{left:140%}
.card-title a{background:linear-gradient(var(--acc),var(--acc)) 0 100%/0 3px no-repeat;padding-bottom:2px;transition:background-size .45s var(--ease),color .2s}
.card:hover .card-title a{background-size:100% 3px}
.card .badge{transition:transform .35s var(--ease)}
.card:hover .badge{transform:translateX(4px)}
.cat-big h3,.row h4{transition:color .2s}
.cat-big:hover h3,.row:hover h4{color:var(--link)}
.row{transition:transform var(--t-med) var(--ease)}
.row:hover{transform:translateX(5px)}
.row .n{transition:transform .3s var(--ease)}
.row:hover .n{transform:scale(1.25)}
.tags a{transition:transform var(--t-fast) var(--ease),background var(--t-fast),color var(--t-fast),border-color var(--t-fast)}
.tags a:hover{transform:translateY(-2px)}
.side-box{transition:box-shadow var(--t-med)}
.side-box:hover{box-shadow:var(--sh)}

/* post page */
.post-hero{overflow:hidden;border-radius:var(--r)}
.post-hero img{animation:pm-kenin 1.4s var(--ease) backwards;transition:transform 1.2s var(--ease)}
.post-hero:hover img{transform:scale(1.03)}
.post-body a{background:linear-gradient(rgba(247,201,40,.45),rgba(247,201,40,.45)) 0 100%/0 40% no-repeat;transition:background-size .35s var(--ease),color .2s}
.post-body a:hover{background-size:100% 40%}
.post-body img{transition:transform .5s var(--ease),box-shadow .5s}
.post-body img:hover{transform:scale(1.02);box-shadow:var(--sh)}
.author-box .avatar{animation:pm-pulse 3.2s ease-out infinite}

/* footer */
.site-footer a{transition:transform .25s var(--ease),color .2s}
.site-footer ul a{display:inline-block}
.site-footer ul a:hover{transform:translateX(5px)}

@media print{.pm-motion [data-rv]{opacity:1!important;animation:none!important}.ticker{display:none!important}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}.ticker-track{animation:none!important}.ticker-viewport{overflow-x:auto}}
/* =================== END MOTION PACK =================== */

body.script:
    //
(function(){
var d=document,$=function(s,c){return (c||d).querySelector(s)},$$=function(s,c){return Array.prototype.slice.call((c||d).querySelectorAll(s))};
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function on(el,ev,fn){if(el)el.addEventListener(ev,fn)}
/* theme */
var root=d.documentElement,tg=$('#theme-toggle');
on(tg,'click',function(){var t=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',t);try{localStorage.setItem('pm-theme',t)}catch(e){}});
/* date, year */
var td=$('#today');if(td)td.textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});
var yr=$('#year');if(yr)yr.textContent=new Date().getFullYear();
/* mobile menu */
var mm=$('#mobile-menu'),mb=$('#menu-toggle'),so=$('#search-overlay');
if(mm){$$('.nav-desktop a').forEach(function(a){var c=a.cloneNode(true);mm.appendChild(c);on(c,'click',function(){mm.classList.remove('is-open')})})}
on(mb,'click',function(){if(so)so.classList.remove('is-open');mm.classList.toggle('is-open')});
/* search */
on($('#search-open'),'click',function(){mm.classList.remove('is-open');so.classList.toggle('is-open');var i=$('input',so);if(i)i.focus()});
on($('#search-close'),'click',function(){so.classList.remove('is-open')});
on(d,'keydown',function(e){if(e.key==='Escape'){so.classList.remove('is-open');mm.classList.remove('is-open')}});
/* back to top + progress */
var tt=$('#to-top'),pg=$('#progress');
on(tt,'click',function(){window.scrollTo({top:0,behavior:'smooth'})});
on(window,'scroll',function(){var y=window.pageYOffset;if(tt)tt.classList.toggle('show',y>600);if(pg){var h=d.documentElement.scrollHeight-window.innerHeight;pg.style.width=(h>0?Math.min(100,y/h*100):0)+'%'}},{passive:true});
/* ad placeholders */
$$('.ad-box').forEach(function(b){if(b.children.length)b.classList.add('filled')});
/* feeds */
function fmt(dt){return dt.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function P(e){var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0];var c=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';var im='';if(e['media$thumbnail']){im=e['media$thumbnail'].url.replace(/\/s\d+(-c)?\//,'/w640-h360-c/').replace(/=s\d+(-c)?$/,'=w640-h360-c')}else{var m=c.match(/<img[^>]+src=["']([^"']+)/);im=m?m[1]:''}
return {t:e.title.$t,u:l?l.href:'#',i:im,d:new Date(e.published.$t),c:(e.category&&e.category[0]&&e.category[0].term)||'',a:(e.author&&e.author[0]&&e.author[0].name.$t)||'',s:c.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,130)}}
function get(label,n,cb){var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+n;fetch(u).then(function(r){return r.json()}).then(function(j){cb((j.feed&&j.feed.entry)||[])}).catch(function(){cb([])})}
function img(p){return p.i?'<img src="'+esc(p.i)+'" alt="'+esc(p.t)+'" loading="lazy" width="640" height="360"/>':''}
function meta(p){return '<div class="meta">'+(p.a?'<span>'+esc(p.a)+'</span><span>&middot;</span>':'')+'<span>'+fmt(p.d)+'</span></div>'}
var R={
hero:function(a){var p=a[0];if(!p)return '';return '<a class="hero" href="'+esc(p.u)+'"'+(p.i?' style="background-image:url('+esc(p.i.replace('w640-h360','w1200-h675'))+')"':'')+'><div class="hero-in">'+(p.c?'<span class="badge">'+esc(p.c)+'</span>':'')+'<h2>'+esc(p.t)+'</h2><p>'+esc(p.s)+'</p>'+meta(p)+'</div></a>'},
cat:function(a){var p=a[0];if(!p)return '<p class="meta">No posts yet.</p>';var h='<a class="cat-big" href="'+esc(p.u)+'"><div class="thumb">'+img(p)+'</div><h3>'+esc(p.t)+'</h3>'+meta(p)+'</a>';a.slice(1).forEach(function(q){h+='<a class="row" href="'+esc(q.u)+'"><div class="thumb">'+img(q)+'</div><div><h4>'+esc(q.t)+'</h4>'+meta(q)+'</div></a>'});return h},
list:function(a){return a.map(function(p,i){return '<a class="row" href="'+esc(p.u)+'"><span class="n">'+(i+1)+'</span><div><h4>'+esc(p.t)+'</h4>'+meta(p)+'</div></a>'}).join('')},
cards:function(a){return '<div class="rel-grid">'+a.map(function(p){return '<article class="card"><a class="card-thumb" href="'+esc(p.u)+'">'+(img(p)||'<span class="ph"></span>')+'</a><div class="card-body"><h3 class="card-title"><a href="'+esc(p.u)+'">'+esc(p.t)+'</a></h3>'+meta(p)+'</div></article>'}).join('')+'</div>'}};
$$('[data-feed]').forEach(function(el){
var label=el.getAttribute('data-feed'),mode=el.getAttribute('data-mode')||'list',n=+el.getAttribute('data-n')||4,fb=el.getAttribute('data-fallback'),rel=el.getAttribute('data-related');
if(mode==='labels'){fetch('/feeds/posts/summary?alt=json&max-results=0').then(function(r){return r.json()}).then(function(j){var c=(j.feed&&j.feed.category)||[];el.innerHTML='<div class="tags">'+c.map(function(x){return '<a href="/search/label/'+encodeURIComponent(x.term)+'">'+esc(x.term)+'</a>'}).join('')+'</div>';el.classList.add('loaded')}).catch(function(){el.classList.add('loaded')});return}
function done(items){if(rel){var here=location.pathname;items=items.filter(function(e){var p=P(e);return p.u.replace(/^https?:\/\/[^\/]+/,'').split('?')[0]!==here})}
items=items.slice(0,n);if(!items.length&&fb==='1'&&label!=='*'){get('',n,done2);return}fill(items)}
function done2(items){fill(items.slice(0,n))}
function fill(items){var a=items.map(P);if(rel&&!a.length){var s=el.closest('.related');if(s)s.style.display='none'}el.innerHTML=a.length||mode==='cat'?R[mode](a):'';el.classList.add('loaded')}
get(label==='*'?'':label,rel?n+1:n,done)});
/* post enhancements */
var body=$('.post-body');
if(body&&$('.post-detail .post-h1')){
var w=(body.innerText||'').trim().split(/\s+/).length,rt=$('#read-time');if(rt)rt.textContent='\u00b7 '+Math.max(1,Math.round(w/200))+' min read';
var hero=$('.post-hero img'),fi=body.querySelector('img');
if(hero&&fi){var k=function(s){return (s||'').split('/').pop().split('?')[0]};if(k(fi.getAttribute('src'))===k(hero.getAttribute('src'))||k(fi.parentNode.getAttribute&&fi.parentNode.getAttribute('href'))===k(hero.getAttribute('src'))){var host=fi.closest('.separator,a')||fi;host.style.display='none'}}
$$('.author-box .avatar,.meta .avatar').forEach(function(a){a.textContent=(a.getAttribute('data-n')||'A').charAt(0).toUpperCase()});
function mv(src,dst,after){var s=$(src),t=$(dst);if(!s||!t)return;var w=$('.widget',s);if(!w){return}if(after){t.parentNode.insertBefore(w,t.nextSibling)}else{t.appendChild(w)}}
mv('#ad-post-top-src','#post-ad-top');mv('#ad-post-bottom-src','#post-ad-bottom');
var ia=$('#ad-in-article-src .widget'),ps=$$('p',body).filter(function(p){return p.parentNode===body});
if(ia){var tgt=ps[2]||ps[ps.length-1];if(tgt)tgt.parentNode.insertBefore(ia,tgt.nextSibling);else body.appendChild(ia)}
var u=encodeURIComponent(location.href),t=encodeURIComponent(d.title);
$$('[data-share]').forEach(function(a){var s=a.getAttribute('data-share'),m={facebook:'https://www.facebook.com/sharer/sharer.php?u='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+t,whatsapp:'https://wa.me/?text='+t+'%20'+u,linkedin:'https://www.linkedin.com/sharing/share-offsite/?url='+u};a.href=m[s];a.target='_blank';a.rel='noopener'});
on($('#copy-link'),'click',function(){var b=this;(navigator.clipboard?navigator.clipboard.writeText(location.href):Promise.reject()).then(function(){b.textContent='Copied!'}).catch(function(){window.prompt('Copy link:',location.href)})})
}
/* in-feed ads */
var grid=$('#posts-grid'),fs=$('#ad-infeed-src .widget');
if(grid&&fs){var cs=$$('.card',grid);if(cs.length>=4){var w=d.createElement('div');w.className='ad-infeed';w.appendChild(fs);grid.insertBefore(w,cs[4]||null)}}
})();

    //

    //
/* MOTION PACK: scroll reveal, button ripple, sliding ticker */
(function(){
var d=document,root=d.documentElement;
function $(s,c){return (c||d).querySelector(s)}
function $$(s,c){return Array.prototype.slice.call((c||d).querySelectorAll(s))}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;

/* header shadow after scrolling */
var hd=$('.site-header');
function sc(){if(hd)hd.classList.toggle('scrolled',window.pageYOffset>12)}
window.addEventListener('scroll',sc,{passive:true});sc();

/* theme toggle spin */
var tg=$('#theme-toggle');
if(tg)tg.addEventListener('click',function(){tg.classList.remove('spin');void tg.offsetWidth;tg.classList.add('spin')});

/* mobile menu stagger index */
$$('#mobile-menu a').forEach(function(a,i){a.style.setProperty('--i',i)});

/* button ripple */
if(!reduce){
var RS='.btn-acc,.pager a,.share a,.share button,.side-search button,.search-overlay button,.icon-btn';
d.addEventListener('pointerdown',function(e){
var b=e.target.closest&&e.target.closest(RS);if(!b)return;
var r=b.getBoundingClientRect(),s=Math.max(r.width,r.height)*2,x=d.createElement('span');
x.className='rip';x.style.width=x.style.height=s+'px';
x.style.left=(e.clientX-r.left-s/2)+'px';x.style.top=(e.clientY-r.top-s/2)+'px';
b.appendChild(x);setTimeout(function(){if(x.parentNode)x.parentNode.removeChild(x)},650)
},{passive:true})}

/* trending ticker */
var tk=$('#ticker'),tr=$('#ticker-track');
if(tk&&tr){
if(!window.fetch){tk.classList.add('off')}else{
fetch('/feeds/posts/default?alt=json&max-results=10').then(function(r){return r.json()}).then(function(j){
var es=(j.feed&&j.feed.entry)||[];
if(!es.length){tk.classList.add('off');return}
var h=es.map(function(e){var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0];return l?'<a href="'+esc(l.href)+'">'+esc(e.title.$t)+'</a>':''}).join('');
tr.innerHTML=h+h.replace(/<a /g,'<a tabindex="-1" aria-hidden="true" ');
tr.style.setProperty('--dur',Math.max(25,(tr.scrollWidth/2)/55)+'s')
}).catch(function(){tk.classList.add('off')})}}

/* scroll reveal */
if(!root.classList.contains('pm-motion')||!('IntersectionObserver' in window))return;
var RULES=[
['.block-title','left'],['.archive-head','left'],['.promo','right'],['.cat-big','up'],['.row','left'],
['.posts-grid .card','card'],['.rel-grid .card','up'],['.side-box','right'],['.pager','up'],
['.crumbs','left'],['.post-h1','up'],['.meta.big','up'],['.post-body > *','body'],
['.post-foot','up'],['.author-box','left'],['.comments','up'],['.footer-grid > *','up'],['.copyright','up']
];
function typeFor(el,t){
if(t==='card'){var all=$$('.posts-grid .card'),i=all.indexOf(el);return window.innerWidth>=640?(i%2?'right':'left'):'up'}
if(t==='body'){
if(/^(SCRIPT|STYLE|BR|NOSCRIPT)$/.test(el.nodeName))return null;
if(el.matches('.widget,.ad-slot')||el.querySelector('.ad-slot,ins,script'))return null;
if(!(el.textContent||'').trim()&&!el.querySelector('img,iframe,video,table'))return null;
if(/^H[2-4]$/.test(el.nodeName)||el.nodeName==='BLOCKQUOTE')return 'left';
if(/^(IMG|FIGURE|TABLE|PRE)$/.test(el.nodeName)||el.classList.contains('separator'))return 'zoom';
return 'up'}
return t}
var io=new IntersectionObserver(function(es){
var vis=es.filter(function(e){return e.isIntersecting}).sort(function(a,b){return a.boundingClientRect.top-b.boundingClientRect.top||a.boundingClientRect.left-b.boundingClientRect.left});
vis.forEach(function(e,i){var el=e.target;el.style.setProperty('--d',(Math.min(i,6)*.08)+'s');el.classList.add('in');io.unobserve(el)})
},{threshold:0,rootMargin:'0px 0px -8% 0px'});
function scan(){
RULES.forEach(function(r){$$(r[0]).forEach(function(el){
if(el.hasAttribute('data-rv')||el.hasAttribute('data-rs'))return;
var p=el.parentNode&&el.parentNode.closest?el.parentNode.closest('[data-rv]'):null;
if(p&&!p.classList.contains('in')){el.setAttribute('data-rs','1');return}
var t=typeFor(el,r[1]);if(!t){el.setAttribute('data-rs','1');return}
el.setAttribute('data-rv',t);io.observe(el)})})}
scan();
/* items that arrive later from feeds */
var tm,mo=new MutationObserver(function(){clearTimeout(tm);tm=setTimeout(scan,60)});
$$('[data-feed],#posts-grid').forEach(function(el){mo.observe(el,{childList:true,subtree:true})});
/* safety nets */
setTimeout(function(){$$('[data-rv]:not(.in)').forEach(function(el){var r=el.getBoundingClientRect();if(r.top<window.innerHeight&&r.bottom>0){el.classList.add('in');io.unobserve(el)}})},3500);
window.addEventListener('beforeprint',function(){$$('[data-rv]:not(.in)').forEach(function(el){el.classList.add('in')})});
})();
    //
